import { cp, mkdir, readdir, rm, stat, writeFile } from 'node:fs/promises';
import path from 'node:path';
import process from 'node:process';

const root = process.cwd();
const distDir = path.join(root, 'dist');
const skillsDir = path.join(root, 'skills');
const promptLibraryDir = path.join(root, 'prompt-library');
const setupDir = path.join(root, 'setup');
const setupCodexSkillsDir = path.join(setupDir, '.codex', 'skills');

async function isDirectory(dir) {
  const info = await stat(dir);
  return info.isDirectory();
}

async function optionalDirectory(dir) {
  return Boolean(await isDirectory(dir).catch(() => false));
}

async function listSkillNames() {
  const sourceSkillsDir = (await optionalDirectory(skillsDir)) ? skillsDir : setupCodexSkillsDir;

  if (!(await optionalDirectory(sourceSkillsDir))) {
    return [];
  }

  const entries = await readdir(sourceSkillsDir, { withFileTypes: true });
  const skillNames = [];

  for (const entry of entries) {
    if (!entry.isDirectory()) {
      continue;
    }

    const skillPath = path.join(sourceSkillsDir, entry.name, 'SKILL.md');
    const info = await stat(skillPath).catch(() => null);
    if (!info?.isFile()) {
      throw new Error(`skills/${entry.name}/SKILL.md is required`);
    }

    skillNames.push(entry.name);
  }

  return skillNames.sort();
}

const skills = await listSkillNames();

await rm(distDir, { recursive: true, force: true });
await mkdir(distDir, { recursive: true });

if (await optionalDirectory(skillsDir)) {
  await cp(skillsDir, path.join(distDir, 'skills'), { recursive: true });
}

if (await optionalDirectory(promptLibraryDir)) {
  await cp(promptLibraryDir, path.join(distDir, 'prompt-library'), { recursive: true });
}

if (await optionalDirectory(setupDir)) {
  await cp(setupDir, path.join(distDir, 'setup'), { recursive: true });
}

await writeFile(
  path.join(distDir, 'manifest.json'),
  `${JSON.stringify({ name: '@symbtech/shipyard', skills }, null, 2)}\n`
);

console.log(`Built @symbtech/shipyard with ${skills.length} skills.`);
